// 个人资料批量更新接口（变体1）：请求体字段直接合并进用户档案对象
const profiles = {}; // 内存档案存储，键为用户名

function loadProfile(username) {
  if (!profiles[username]) {
    profiles[username] = {
      username: username,
      plan: 'free',   // 套餐等级：free / pro，仅服务端可改
      price: 0,       // 计费单价（元/月），仅服务端可改
      note: '',       // 用户自定义备注
      updatedAt: null
    };
  }
  return profiles[username];
}

// 入口：模拟 HTTP PUT /api/profile/:username 的处理函数，req.body 为外部输入
function handleBatchUpdate(username, req) {
  const record = loadProfile(username);
  // 展开合并为定义自有属性语义（即便 body 带 __proto__ 键也只会成为自身属性），
  // 但未做字段白名单：plan/price 等业务字段可被请求体任意覆盖
  const updated = { ...record, ...req.body };
  updated.updatedAt = new Date().toISOString();
  profiles[username] = updated; // 写回存储，篡改结果持久生效
  return updated;
}

// 攻击者请求：在 body 中夹带 plan/price，越权把免费套餐改成负单价
const attackerReq = { body: { note: 'hi', plan: 'pro', price: -999 } };
console.log(handleBatchUpdate('alice', attackerReq));
```

