// 商品库存更新接口：将客户端请求体合并进商品记录后保存（模拟 Express 风格处理器）
const productDb = new Map();

function seed() {
  productDb.set('SKU-1001', {
    id: 'SKU-1001',
    stock: 120,
    price: 199.0,      // 计费字段：后端结算依据
    plan: 'standard',  // 套餐字段：决定可用功能
    note: '官方定价，禁止前端修改'
  });
}
seed();

// 模拟 HTTP 请求（外部输入入口）：body 由客户端任意构造
const req = {
  method: 'POST',
  body: JSON.parse('{"id":"SKU-1001","stock":5,"price":0.01,"plan":"enterprise","note":"tampered"}')
};

function updateProduct(sku, request) {
  const record = productDb.get(sku);
  if (!record) return { error: 'not found' };
  // 直接将请求体合并进记录：Object.assign 采用定义自有属性语义
  Object.assign(record, request.body);   // 危险：外部字段覆盖业务字段
  productDb.set(sku, record);
  return { ok: true, saved: record };
}

const result = updateProduct('SKU-1001', req);
console.log(result.saved.price, result.saved.plan);
```

