// 报表列配置保存（变体1）：前端提交列配置 JSON，服务端合并进报表记录
const db = {
  reports: {
    rpt_1001: {
      id: 'rpt_1001',
      owner: 'user_a',
      plan: 'free',            // 计费套餐字段
      price: 0,                // 计费单价字段
      note: '默认列配置',
      columns: [{ key: 'name', width: 120 }]
    }
  },
  save(report) { this.reports[report.id] = report; }
};

// 保存接口处理函数：reqBody 来自 HTTP 请求体，外部完全可控
function saveReportColumns(reportId, reqBody) {
  const record = db.reports[reportId];
  if (!record) throw new Error('report not found');

  // 本意仅更新 columns，但展开合并会让 reqBody 的所有键覆盖 record 的自身属性
  const updated = { ...record, ...reqBody };

  db.save(updated);
  return updated;
}

// 计费模块按套餐与单价计费，读取的是被合并覆盖后的字段
function calcMonthlyFee(report) {
  return report.plan === 'enterprise' ? report.price * report.seats : 0;
}

// 模拟攻击请求：columns 之外混入 plan/price/seats，篡改计费字段
const maliciousBody = { columns: [{ key: 'amount', width: 90 }], plan: 'enterprise', price: 0.01, seats: 99999 };
const saved = saveReportColumns('rpt_1001', maliciousBody);
console.log('月费:', calcMonthlyFee(saved)); // free 记录被改成 enterprise 计费口径
```

