// 订单收货信息更新接口（变体1）：买家提交收货人、电话、地址等修改
const express = require('express');
const router = express.Router();
router.use(express.json()); // 把 JSON 请求体解析到 req.body

// 模拟订单表：订单号 -> 订单记录；price 由服务端按配送计划计算，note 为客服内部备注
const orderTable = {
  SO202406010001: {
    orderId: 'SO202406010001',
    receiver: '张三',
    phone: '13800000000',
    address: '上海市浦东新区世纪大道100号',
    plan: 'standard',   // 配送计划：standard / nextday
    price: 1990,        // 应付金额（分），不应允许客户端改写
    note: ''
  }
};

// PUT /api/order/:id/shipping —— 请求体即收货信息修改表单
router.put('/api/order/:id/shipping', function updateShipping(req, res) {
  const record = orderTable[req.params.id];
  if (!record) {
    return res.status(404).json({ error: 'order not found' });
  }

  // 直接用请求体展开覆盖订单记录的全部同名字段后写回订单表（无字段白名单）
  const updated = { ...record, ...req.body };
  orderTable[req.params.id] = updated;

  return res.json({ ok: true, order: updated });
});

module.exports = router;
```
